-- Catecismo Maior de Westminster — Parte 1 (Perguntas 1–98)
-- Pré-requisito: migration 021_confessions_catechisms.sql já executada
-- Execute no Supabase SQL Editor ANTES de seed-cmw-maior-parte2.sql

DO $$
DECLARE
  v_doc_id uuid;
BEGIN
  SELECT id INTO v_doc_id
  FROM public.lampas_confessional_documents
  WHERE slug = 'catecismo-maior-westminster';

  IF v_doc_id IS NULL THEN
    RAISE EXCEPTION 'Documento catecismo-maior-westminster não encontrado. Execute a migration 021 primeiro.';
  END IF;

  ON CONFLICT (document_id, number) DO UPDATE SET
    number_label    = EXCLUDED.number_label,
    question        = EXCLUDED.question,
    answer          = EXCLUDED.answer,
    doctrine_tags   = EXCLUDED.doctrine_tags,
    bible_references = EXCLUDED.bible_references,
    sort_order      = EXCLUDED.sort_order,
    metadata        = public.lampas_confessional_questions.metadata || EXCLUDED.metadata;

  RAISE NOTICE 'Catecismo Maior de Westminster (Parte 1 — Q1-98): inseridas/atualizadas.';
END;
$$;
